function orientedBox(cx, cy, length, width, angle) {
  const dx = Math.cos(angle) * length / 2;
  const dy = Math.sin(angle) * length / 2;
  const nx = -Math.sin(angle) * width / 2;
  const ny = Math.cos(angle) * width / 2;
  return [
    [cx + dx + nx, cy + dy + ny],
    [cx + dx - nx, cy + dy - ny],
    [cx - dx - nx, cy - dy - ny],
    [cx - dx + nx, cy - dy + ny],
  ];
}

